4. After line ~163 Schur complement, compute `d_floor`:
   ```cpp
   // Mean of diag(H) — additive floor for rank-collapsed coordinates.
   double d_floor = 0.0;
   for (int a = 0; a < n_lam; ++a) d_floor += H[a*n_lam + a];
   d_floor /= std::max(n_lam, 1);
   ```
5. Save δ-pre-damp Hessian quadratic form for gain ratio. Either (a) before damping, save `H_pre` as a copy and compute `delta_H_delta = δᵀ H_pre δ` after solving for δ; or (b) compute `delta_H_delta = G·δ - 0.5·δᵀ·(damping_diff)·δ` analytically. Choose (a) for clarity. **Pre-damp copy of `H` adds O(n_lam²) memory = 80×80 = 6.4K doubles = trivial.**
6. Replace trust-region block (lines ~184-208) with:
   ```cpp
   // Save H pre-damp for gain-ratio quadratic form δᵀHδ (used after solve).
   std::vector<double> H_pre(H);  // 80×80 copy — negligible.

   // 5h. LM damped solve with FAILED retry. Cap retries to 3.
   bool solve_ok = false;
   double g_dot_d = 0.0, delta_H_delta = 0.0;
   for (int retry = 0; retry < 3 && !solve_ok; ++retry) {
       // Restore H from H_pre (LDLT factored in-place destroys H).
       std::copy(H_pre.begin(), H_pre.end(), H.begin());
       // Apply scale-invariant damping with additive floor.
       for (int a = 0; a < n_lam; ++a) {
           H[a*n_lam + a] = std::max(H[a*n_lam + a] * (1.0 + lm_mu),
                                      lm_mu * d_floor);
       }
       std::copy(G.begin(), G.end(), delta.begin());
       if (ldlt_factor_inplace(H.data(), static_cast<size_t>(n_lam), 1e-12) != RK_OK) {
           lm_mu = std::min(lm_mu_max, lm_mu * 10.0);
           continue;
       }
       ldlt_solve(H.data(), static_cast<size_t>(n_lam), delta.data());
       solve_ok = true;
   }
   if (!solve_ok) {
       res.base.status = RK_ERR_BADARG;
       std::snprintf(res.message, sizeof(res.message),
           "newton_kl: LDLT failed 3× even at lm_mu=%.2e", lm_mu);
       res.lm_mu_final = lm_mu;
       return res;
   }

   // δᵀ H δ using pre-damp Hessian (PSD) — for gain ratio.
   delta_H_delta = 0.0;
   for (int a = 0; a < n_lam; ++a)
       for (int b = 0; b < n_lam; ++b)
           delta_H_delta += delta[a] * H_pre[a*n_lam + b] * delta[b];
   for (int a = 0; a < n_lam; ++a) g_dot_d += G[a] * delta[a];
   ```
7. Replace Armijo block (lines ~217-237) with three-way bookkeeping:
   ```cpp
   double alpha = 1.0;
   double Z_trial = 0.0, g_trial = 0.0, u_max_trial = 0.0;
   constexpr double c1 = 1e-4;
   bool accepted = false;
   for (int ls = 0; ls < 30; ++ls) {
       for (int a = 0; a < n_lam; ++a) lam_trial[a] = lam[a] - alpha * delta[a];
       g_trial = eval_dual(lam_trial, Z_trial, u_max_trial);
       if (g_trial <= g_curr - c1 * alpha * g_dot_d) { accepted = true; break; }
       alpha *= 0.5;
   }
   res.line_alpha = alpha;

   if (!accepted) {
       // FAILED — back off lm_mu and re-solve next iter; do NOT advance λ.
       lm_mu = std::min(lm_mu_max, lm_mu * 10.0);
       continue;  // restart iter (without incrementing iter counter? — see step 8)
   }

   // Marquardt gain ratio.
   const double predicted = alpha * g_dot_d - 0.5 * alpha * alpha * delta_H_delta;
   const double rho = (g_curr - g_trial) / std::max(predicted, 1e-300);

   if (alpha >= 0.999 && rho > 0.75) {
       lm_mu = std::max(lm_mu_min, lm_mu / 3.0);
   } else if (rho < 0.25) {
       // Poor model — back off but DO advance λ this iter (since accepted).
       lm_mu = std::min(lm_mu_max, lm_mu * 10.0);
   }
   // else: keep lm_mu unchanged.

   // Update λ.
   double step2 = 0.0;
   for (int a = 0; a < n_lam; ++a) {
       const double d = alpha * delta[a];
       lam[a] -= d;
       step2 += d * d;
   }
   res.step_norm = std::sqrt(step2);
   g_curr     = g_trial;
   Z_curr     = Z_trial;
   u_max_curr = u_max_trial;
   ```
8. Note in step 7: `continue` in the FAILED path means we re-enter the iter loop. Add a `failed_retry_count` to break out after 3 failed iters in a row (otherwise infinite loop on hopeless problem):
